import { MultiMeterBarChartInternalTooltipConfig } from './multi-meter-bar-chart-internal.js';
import { LegendItem } from '../../../core/components/legend/categorical/types/legend.js';
import { TooltipItem } from '../../../core/types/tooltip.js';

export interface MultiMeterBarChartSegmentData {
  color: string;
  id: string;
  name: string;
  value: number;
}

export interface MultiMeterBarChartState {
  segments: MultiMeterBarChartSegmentData[];
  visibleSegments: Map<string, MultiMeterBarChartSegmentData>;
  highlightedSegments?: LegendItem[];
  tooltip: MultiMeterBarTooltipState;
}

export const initialState: MultiMeterBarChartState = {
  segments: [],
  visibleSegments: new Map(null),
  tooltip: { visible: false, pinned: false },
};

export interface MultiMeterBarTooltipState {
  pinned: boolean;
  visible: boolean;
  content?: TooltipItem;
}

export interface MultiMeterBarChartTooltipContextData {
  label: string;
  tooltipConfig: MultiMeterBarChartInternalTooltipConfig;
}

export interface MultiMeterBarChartTooltipContextDataProps {
  data: MultiMeterBarChartTooltipContextData;
}
